    def get_union_size(level, position):
        def dfs(l, p):
            result = sets[(l, p)]
            if left[l][p] != -1:
                result.update(dfs(l + 1, left[l][p]))
            if right[l][p] != -1:
                result.update(dfs(l +1, right[l][p]))
            return result

        return len(dfs(level, position))

